"""Real browser checks; launch a local preview first (npm run preview -- --port 4173)."""
import os,json,time,threading,http.server,functools,atexit
from pathlib import Path
os.environ.setdefault('PLAYWRIGHT_BROWSERS_PATH','/workspace/.playwright')
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
ART=ROOT.parents[1]/'artifacts'/'web';ART.mkdir(parents=True,exist_ok=True)
server=http.server.ThreadingHTTPServer(('127.0.0.1',4177),functools.partial(http.server.SimpleHTTPRequestHandler,directory=str(ROOT/'dist')))
threading.Thread(target=server.serve_forever,daemon=True).start()
results=[];errors=[];completed=False
@atexit.register
def write_report():
 (ART/'qa-report.json').write_text(json.dumps({'browser':'Chromium / Playwright Python','renderer':'SwiftShader software WebGL; no physical GPU claimed','completed':completed,'passed':completed and all(t['passed'] for t in results),'tests':results,'errors':errors},indent=2,ensure_ascii=False))
def check(name,value,details=None):
 results.append({'name':name,'passed':bool(value),'details':details})
 if not value: raise AssertionError(name)
with sync_playwright() as p:
 browser=p.chromium.launch(headless=True,args=['--no-sandbox','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--disable-dev-shm-usage'])
 page=browser.new_page(viewport={'width':1440,'height':1000},device_scale_factor=1)
 page.on('pageerror',lambda e:errors.append(str(e)))
 page.goto('http://127.0.0.1:4177/');page.wait_for_timeout(1500)
 check('A editorial heading',page.get_by_role('heading',name='A forma da pausa.').is_visible())
 check('A desktop no overflow',page.evaluate('document.documentElement.scrollWidth<=innerWidth'))
 for y in range(0,3500,650): page.evaluate('(y)=>scrollTo(0,y)',y);page.wait_for_timeout(200)
 page.wait_for_timeout(900);page.evaluate('scrollTo(0,0)');page.wait_for_timeout(500)
 page.screenshot(path=str(ART/'a-desktop.png'),full_page=True)
 page.get_by_role('link',name='Conheça Object 01').click();page.wait_for_function("document.querySelector('.scene-host').dataset.render==='webgl'",timeout=30000)
 page.wait_for_timeout(1400)
 check('B original GLB loaded',page.locator('.scene-host').get_attribute('data-source')=='glb')
 pixel=page.evaluate('''()=>{const c=document.querySelector('canvas');const gl=c.getContext('webgl2');const a=new Uint8Array(4);gl.readPixels(c.width/2,c.height/2,1,1,gl.RGBA,gl.UNSIGNED_BYTE,a);return {pixel:[...a],width:c.width,height:c.height,renderer:gl.getParameter(gl.RENDERER)}}''')
 check('WebGL actual framebuffer nonblack',sum(pixel['pixel'][:3])>0,pixel)
 page.get_by_role('button',name='Oliva mineral',exact=True).click()
 check('material selected',page.get_by_role('button',name='Oliva mineral',exact=True).get_attribute('aria-pressed')=='true')
 page.locator('#light').focus();page.keyboard.press('Home')
 for _ in range(30): page.keyboard.press('ArrowRight')
 page.wait_for_timeout(300)
 check('light updates',page.locator('.scene-host').get_attribute('data-intensity')=='30')
 canvas=page.locator('canvas');canvas.focus();page.keyboard.press('ArrowRight');page.keyboard.press('+')
 before=page.locator('.scene-host').get_attribute('data-camera');box=canvas.bounding_box();page.mouse.move(box['x']+box['width']/2,box['y']+box['height']/2);page.mouse.down();page.mouse.move(box['x']+box['width']/2+120,box['y']+box['height']/2,steps=8);page.mouse.up();page.wait_for_timeout(400)
 check('pointer orbit changes camera',page.locator('.scene-host').get_attribute('data-camera')!=before)
 page.evaluate('document.activeElement.blur();scrollTo(0,0)');page.wait_for_timeout(300);page.screenshot(path=str(ART/'b-desktop.png'),full_page=True)
 page.set_viewport_size({'width':1440,'height':600});page.locator('footer').scroll_into_view_if_needed();page.wait_for_timeout(700)
 check('offscreen scene paused',page.locator('.scene-host').get_attribute('data-paused')=='true')
 page.locator('.experience').scroll_into_view_if_needed();page.wait_for_timeout(200)
 has_extension=page.evaluate("()=>{const ext=document.querySelector('canvas').getContext('webgl2').getExtension('WEBGL_lose_context');if(ext)ext.loseContext();return !!ext}");check('real WEBGL_lose_context supported',has_extension);page.wait_for_function("document.querySelector('.scene-host').dataset.render==='context-lost'")
 check('context loss explicit fallback',page.locator('.scene-host').get_attribute('data-render')=='context-lost')
 check('context loss shows reference',page.locator('.fallback-image').is_visible())
 check('context fallback releases input',page.locator('canvas').evaluate("el=>el.tabIndex===-1&&el.style.pointerEvents==='none'&&el.style.touchAction==='auto'"))
 page.screenshot(path=str(ART/'b-context-lost.png'))
 page.goto('http://127.0.0.1:4177/product.html?noWebGL=1');page.wait_for_timeout(700)
 check('no WebGL explicit fallback',page.locator('.scene-host').get_attribute('data-render')=='fallback')
 page.screenshot(path=str(ART/'b-no-webgl.png'),full_page=True)
 mobile=browser.new_context(viewport={'width':390,'height':844},is_mobile=True,has_touch=True,reduced_motion='reduce')
 m=mobile.new_page();m.on('pageerror',lambda e:errors.append(str(e)))
 m.goto('http://127.0.0.1:4177/');m.wait_for_timeout(500)
 check('A mobile reduced motion content visible',m.get_by_role('heading',name='A forma da pausa.').is_visible())
 check('A mobile no overflow',m.evaluate('document.documentElement.scrollWidth<=innerWidth'))
 m.screenshot(path=str(ART/'a-mobile.png'),full_page=True)
 m.get_by_role('button',name='Abrir navegação').tap();check('mobile accessible menu',m.get_by_role('button',name='Abrir navegação').get_attribute('aria-expanded')=='true')
 m.get_by_role('link',name='Explorar Object 01').tap();m.wait_for_function("document.querySelector('.scene-host').dataset.render==='webgl'",timeout=30000)
 m.wait_for_function("document.querySelector('.scene-host').dataset.rotation!==undefined");rotation=m.locator('.scene-host').get_attribute('data-rotation');m.evaluate('scrollBy(0,120)');m.wait_for_timeout(350);check('reduced motion disables scroll rotation',m.locator('.scene-host').get_attribute('data-rotation')==rotation)
 m.get_by_role('button',name='Carvão acetinado',exact=True).tap();check('touch material control',m.get_by_role('button',name='Carvão acetinado',exact=True).get_attribute('aria-pressed')=='true')
 check('B mobile no overflow',m.evaluate('document.documentElement.scrollWidth<=innerWidth'))
 m.locator('canvas').scroll_into_view_if_needed();m.wait_for_timeout(300);before=m.locator('.scene-host').get_attribute('data-camera');box=m.locator('canvas').bounding_box();cdp=mobile.new_cdp_session(m);x=box['x']+box['width']/2;y=max(120,box['y']+box['height']/2)
 cdp.send('Input.dispatchTouchEvent',{'type':'touchStart','touchPoints':[{'x':x,'y':y}]})
 cdp.send('Input.dispatchTouchEvent',{'type':'touchMove','touchPoints':[{'x':x+80,'y':y+10}]})
 cdp.send('Input.dispatchTouchEvent',{'type':'touchEnd','touchPoints':[]});m.wait_for_timeout(500)
 check('touch drag changes camera',m.locator('.scene-host').get_attribute('data-camera')!=before)
 m.evaluate('document.activeElement.blur();scrollTo(0,0)');m.wait_for_timeout(300);m.screenshot(path=str(ART/'b-mobile.png'),full_page=True)
 pending=[];late=browser.new_page(viewport={'width':1200,'height':900});late.route('**/assets/scene-*.js',lambda route:pending.append(route));late.goto('http://127.0.0.1:4177/product.html');late.wait_for_timeout(300);late.get_by_role('button',name='Oliva mineral',exact=True).click();pending[0].continue_();late.wait_for_function("document.querySelector('.scene-host').dataset.source==='glb'",timeout=30000)
 check('async import preserves selected material',late.locator('.scene-host').get_attribute('data-material')=='olive')
 check('async import applies actual surface color',late.locator('.scene-host').get_attribute('data-surface-color')=='727a5f')
 late.close();pending=[];late=browser.new_page();late.route('**/aura-object-01.glb',lambda route:pending.append(route));late.goto('http://127.0.0.1:4177/product.html');late.wait_for_selector('canvas');late.wait_for_timeout(200);late.evaluate("document.querySelector('canvas').getContext('webgl2').getExtension('WEBGL_lose_context').loseContext()");late.wait_for_function("document.querySelector('.scene-host').dataset.render==='context-lost'");pending[0].continue_();late.wait_for_timeout(1000)
 check('late GLB cannot hide context fallback',late.locator('.scene-host').get_attribute('data-render')=='context-lost' and 'loaded' not in late.locator('.scene-host').get_attribute('class'))
 late.close()
 check('zero uncaught page errors',len(errors)==0,errors)
 browser.close()
server.shutdown()
completed=True
write_report()
print(json.dumps(results,indent=2,ensure_ascii=False))
